CREATE OR REPLACE VIEW `vwcogeprovvigioni` AS select `p`.`datacontabile` AS `del`,`c`.`conto_dare` AS `conto_dare`,sum(`p`.`importo`) AS `importo`,`c`.`descrizione_dare` AS `descrizione_dare`,`c`.`conto_avere` AS `conto_avere`,`c`.`descrizione_avere` AS `descrizione_avere` from (`vwprovv2cogedetail` `p` join `coges` `c` on(((`c`.`entrata_uscita` = `p`.`entrata_uscita`) and (`c`.`fonte` = `p`.`fonte`)))) group by `p`.`fonte`,`p`.`entrata_uscita`
